import { toModelEntry } from 'jsr:@skmtc/core@0.28.3'
import { ZodProjection } from "./ZodProjection.ts";
import { toEnrichmentSchema, type EnrichmentSchema } from "./enrichments.ts";
import denoJson from "../deno.json" with { type: "json" };

export const zodEntry = toModelEntry<EnrichmentSchema>({
  id: denoJson.name,
  toEnrichmentSchema,
  transform({ context, refName }) {
    context.insertModel(ZodProjection, refName);
  },
});
import { camelCase, decapitalize } from 'jsr:@skmtc/core@0.28.3'
import { toTsModelProjectionBase } from 'jsr:@skmtc/lang-typescript@0.12.17'
import { join } from "jsr:@std/path@^1.1.2";
import { toEnrichmentSchema, type EnrichmentSchema } from "./enrichments.ts";
import denoJson from "../deno.json" with { type: "json" };

export const ZodBase = toTsModelProjectionBase<EnrichmentSchema>({
  id: denoJson.name,

  toIdentifierName({ refName }): string {
    return decapitalize(camelCase(refName));
  },

  toIdentifierType: () => ({ type: "variable" }),

  toExportPath({ refName, enrichments, variant }): string {
    const name = this.toIdentifierName({ refName, enrichments, variant });

    return join("@", "types", `${decapitalize(name)}.generated.ts`);
  },

  toEnrichmentSchema,
});
import { emptyEnrichmentSchema, type EmptyEnrichments } from 'jsr:@skmtc/core@0.28.3'

export const toEnrichmentSchema = () => emptyEnrichmentSchema

export type EnrichmentSchema = EmptyEnrichments
