  identifier: TsIdentifier
  value: Value
  destinationPath: string
  /** JSDoc description rendered above the declaration. */
  description?: string
  /** A `//` line comment rendered verbatim above the declaration (see {@link TsDefinition}). */
  leadingComment?: string
  noExport?: boolean
}

