import { camelCase, OasVoid } from '@skmtc/core'
import type {
  GenerateContextType,
  OasOperation,
  OasParameter,
  OasRef,
  OasSchema,
  Stringable
} from '@skmtc/core'
import { TsMethod, TsSnippet, toPathTemplate } from '@skmtc/lang-typescript'
import { ZodProjection } from '@skmtc/gen-zod'

/** Deterministic method name from method + path: `GET /orders/{id}` → `getOrdersId`. */
export const toMethodName = (operation: OasOperation): string => {
  return `${operation.method}${camelCase(operation.path, { upperFirst: true })}`
}

type PathParameterArgs = {
  context: GenerateContextType
  parameter: OasParameter
}

export class PathParameter extends TsSnippet {
  name: string
  paramType: string

  constructor({ context, parameter }: PathParameterArgs) {
    super({ context })

    // Name stays unsanitized so it matches the `${name}` slot in the
    // fetch path template.
    this.name = parameter.name

    const schema = parameter.schema?.isRef() ? parameter.schema.resolve() : parameter.schema

    this.paramType =
      schema?.type === 'integer' || schema?.type === 'number'
        ? 'number'
        : schema?.type === 'boolean'
          ? 'boolean'
          : 'string'
  }

  override toString(): string {
    return `${this.name}: ${this.paramType}`
  }
}

type BodyParameterArgs = {
  context: GenerateContextType
  destinationPath: string
  schema: OasSchema | OasRef<'schema'>
  fallbackName: string
}

export class BodyParameter extends TsSnippet {
  schemaName: string

  constructor({ context, destinationPath, schema, fallbackName }: BodyParameterArgs) {
    super({ context })

    const definition = context.insertNormalizedModel(ZodProjection, {
      schema,
      fallbackName,
      destinationPath
    })

    this.schemaName = definition.identifier.name

    this.register({ imports: { zod: ['z'] }, destinationPath })
  }

  override toString(): string {
    return `body: z.infer<typeof ${this.schemaName}>`
  }
}

type MethodBodyArgs = {
  context: GenerateContextType
  operation: OasOperation
  destinationPath: string
  hasBody: boolean
}

export class MethodBody extends TsSnippet {
  responseName: string
  path: string
